(() => {
  let viewer,currentBranch,currentPhotos=[],currentIndex=0,returnFocus,previousOverflow='';
  const element=(tag,className,text)=>{const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;};
  const validPhotos=branch=>(branch.photos??[]).filter(photo=>/^assets\/branches\/\d+\/\d+-thumb\.webp$/.test(photo.src??'')&&/^assets\/branches\/\d+\/\d+-full\.webp$/.test(photo.full??''));
  function emptyCover(branch){const cover=element('div','branch-photo-empty');const logo=element('img');logo.src='assets/checkmat-logo.webp';logo.alt='';logo.setAttribute('aria-hidden','true');logo.width=144;logo.height=46;cover.append(logo,element('span','',branch.photoStatus==='unavailable'?'Fotos indisponíveis no momento':'Fotos ainda não cadastradas'));return cover;}
  function ensureViewer(){if(viewer)return;
    const dialog=element('dialog','photo-dialog');dialog.id='branch-photo-dialog';dialog.setAttribute('aria-labelledby','photo-dialog-title');
    const header=element('div','photo-dialog-header');const heading=element('div');const title=element('h2','','');title.id='photo-dialog-title';const location=element('p','photo-dialog-location');heading.append(title,location);const close=element('button','photo-close','Fechar');close.type='button';close.setAttribute('aria-label','Fechar galeria de fotos');close.addEventListener('click',()=>dialog.close());header.append(heading,close);
    const stage=element('div','photo-stage');const image=element('img','photo-full');image.decoding='async';const failure=element('p','photo-error','Não foi possível abrir esta foto. Tente outra imagem da galeria.');failure.hidden=true;image.addEventListener('error',()=>{image.hidden=true;failure.hidden=false;});image.addEventListener('load',()=>{image.hidden=false;failure.hidden=true;});stage.append(image,failure);
    const controls=element('div','photo-controls');const previous=element('button','photo-step','Anterior');previous.type='button';previous.setAttribute('aria-label','Foto anterior');const counter=element('p','photo-counter');counter.setAttribute('role','status');counter.setAttribute('aria-live','polite');const next=element('button','photo-step','Próxima');next.type='button';next.setAttribute('aria-label','Próxima foto');controls.append(previous,counter,next);
    const thumbnails=element('div','photo-thumbnails');thumbnails.setAttribute('role','group');thumbnails.setAttribute('aria-label','Escolha uma foto da academia');
    const footer=element('p','photo-source','Fotos cadastradas pela unidade na Checkmat Brasil.');
    dialog.append(header,stage,controls,thumbnails,footer);document.body.append(dialog);
    previous.addEventListener('click',()=>showPhoto((currentIndex-1+currentPhotos.length)%currentPhotos.length));next.addEventListener('click',()=>showPhoto((currentIndex+1)%currentPhotos.length));
    dialog.addEventListener('keydown',event=>{if(currentPhotos.length>1&&(event.key==='ArrowLeft'||event.key==='ArrowRight')){event.preventDefault();showPhoto((currentIndex+(event.key==='ArrowLeft'?-1:1)+currentPhotos.length)%currentPhotos.length);}});
    dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
    dialog.addEventListener('close',()=>{document.body.style.overflow=previousOverflow;image.removeAttribute('src');if(returnFocus?.isConnected)returnFocus.focus();currentBranch=null;currentPhotos=[];});
    viewer={dialog,title,location,image,failure,previous,next,counter,thumbnails};
  }
  function showPhoto(index){currentIndex=index;const photo=currentPhotos[index];if(!photo)return;viewer.failure.hidden=true;viewer.image.hidden=false;viewer.image.alt=`Foto ${index+1} cadastrada para ${currentBranch.name}`;viewer.image.width=photo.fullWidth;viewer.image.height=photo.fullHeight;viewer.image.src=photo.full;viewer.counter.textContent=`${index+1} de ${currentPhotos.length}`;[...viewer.thumbnails.children].forEach((button,buttonIndex)=>button.setAttribute('aria-pressed',String(buttonIndex===index)));}
  function openGallery(branch,trigger){const photos=validPhotos(branch);if(!photos.length)return;ensureViewer();currentBranch=branch;currentPhotos=photos;returnFocus=trigger;viewer.title.textContent=branch.name;viewer.location.textContent=[branch.city,branch.state,branch.country].filter(Boolean).join(' · ');viewer.previous.hidden=photos.length<2;viewer.next.hidden=photos.length<2;viewer.thumbnails.hidden=photos.length<2;
    viewer.thumbnails.replaceChildren(...photos.map((photo,index)=>{const button=element('button','photo-thumb');button.type='button';button.setAttribute('aria-label',`Ver foto ${index+1} de ${photos.length}`);button.setAttribute('aria-pressed',String(index===0));const image=element('img');image.src=photo.src;image.alt='';image.width=photo.width;image.height=photo.height;button.append(image);button.addEventListener('click',()=>showPhoto(index));return button;}));showPhoto(0);previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';viewer.dialog.showModal();}
  function createCover(branch){const photos=validPhotos(branch);if(!photos.length)return emptyCover(branch);const button=element('button','branch-photo-open');button.type='button';button.setAttribute('aria-label',`Ver ${photos.length===1?'foto':'fotos'} de ${branch.name}`);const photo=photos[0];const image=element('img','branch-photo');image.src=photo.src;image.alt=`Foto cadastrada para ${branch.name}`;image.loading='lazy';image.decoding='async';image.width=photo.width;image.height=photo.height;image.addEventListener('error',()=>button.replaceWith(emptyCover(branch)),{once:true});const badge=element('span','branch-photo-count',`${photos.length} ${photos.length===1?'foto':'fotos'}`);const label=element('span','branch-photo-label','Ver fotos da unidade');button.append(image,badge,label);button.addEventListener('click',()=>openGallery(branch,button));return button;}
  window.CheckmatBranchGallery={createCover};
})();